#include <iostream>
#include <string>
using namespace std;

int main() {
    string s = "{w}{tail}";
    string t = "{w}";

    if (s.find(t) != string::npos) {
        cout << "找到了喵" << endl;
    } else {
        cout << "没有喵" << endl;
    }
    return 0;
}
